import type { MetricKey } from '../config/thresholds'
import type { DataOrigin, Provenance } from '../data/types'

/**
 * How real a value is, in the four classes the interface draws differently:
 *
 *   sim    generated by the simulator: nobody and nothing was measured
 *   model  computed by this app from real NASA / NOAA data
 *   real   measured or reported: a sensor, a telemetry backend, the crew member's own entry
 *   none   no instrument is connected, so there is no value
 */
export type SourceClass = 'sim' | 'model' | 'real' | 'none'

export const sourceClassOf = (o: DataOrigin): SourceClass => (o === 'simulated' ? 'sim' : o === 'modelled' ? 'model' : o === 'none' ? 'none' : 'real')

/** Origin of one metric in a sample. A sample without provenance comes from the simulator. */
export const originOf = (provenance: Provenance | undefined, k: MetricKey): DataOrigin => provenance?.[k] ?? 'simulated'

/** The class of a card with several values: the least real one decides, so one simulated value marks the whole card. */
export function mixSources(origins: readonly DataOrigin[]): SourceClass {
  const present = new Set(origins.map(sourceClassOf))
  return (['sim', 'model', 'real', 'none'] as const).find((c) => present.has(c)) ?? 'none'
}
